local function Call(cmd, ...)
  local r = table.pack(pcall(funcLuaCommand, cmd, ...))
  if not r[1] then
    return nil
  end
  return table.unpack(r, 2, r.n)
end

local function Int(v)
  if type(v) ~= "number" then
    return 0
  end
  return math.floor(v + 0.5)
end

--- Advanced: Namespace: mouse pointer tracker for menus; holds new().
VRFW.pointer = VRFW.pointer or {}
--- Advanced: Creates a mouse pointer tracker; answers a table with zone setters (rect, box, inst), position, at, poll and reset.
VRFW.pointer.new = VRFW.pointer.new or function()
  local P = {zones = {}, on = false, x = nil, y = nil, hot = nil, prev = {}, edge_t = 0, REPEAT = 10}
  local MOVED, POS, GPOS, CHECK, CTRL = 3272825600, 558229292, 4002164178, 4265778440, 1332654303
  local LEFT, CLICK = 749879980 --[[CMD_VRFW_MOUSE_LEFT]], 1651523701 --[[CMD_ENTER_CLICK]]
  local W_UP, W_DOWN = 2649361876 --[[CMD_VRFW_WHEEL_UP]], 1098743808 --[[CMD_VRFW_WHEEL_DOWN]]
  local NAV = {1197218715, 3259546669, 2765147006, 2075023265} -- CMD_UP / DOWN / LEFT / RIGHT
  local CTRLS = {CTRL, 2748927068 --[[analog-move control: the stick's menu moves]]}
  local function M(cmd, ...)
    local ok, a, b = pcall(funcLuaMenuCommand, cmd, ...)
    if ok then return a, b end
    return nil
  end
  local function In(cmd, ctrl)
    local ok, r = pcall(funcLuaCommand, CHECK, ctrl or CTRL, cmd)
    return ok and r == true
  end
  local function Edge(cmd, ctrl)
    local key = ctrl and (tostring(ctrl) .. ":" .. tostring(cmd)) or cmd
    local now = In(cmd, ctrl)
    local was = P.prev[key]
    P.prev[key] = now
    return now and not was
  end
  --- Starts a new list of pointer zones for this frame.
  function P.begin()
    P.zones = {}
  end
  --- Adds a zone by top-left corner and size; `id` is what P.at answers, `edge` as in P.poll.
  function P.rect(x, y, w, h, id, edge)
    P.zones[#P.zones + 1] = {x, y, x + w, y + h, id = id, edge = edge}
  end
  --- Adds a zone by centre and half sizes; `id` and `edge` as in P.rect.
  function P.box(cx, cy, hw, hh, id, edge)
    P.zones[#P.zones + 1] = {cx - hw, cy - hh, cx + hw, cy + hh, id = id, edge = edge}
  end
  --- Adds a zone that follows instance idx of a layer, with half sizes hw and hh.
  function P.inst(layer, idx, hw, hh, id, edge)
    P.zones[#P.zones + 1] = {layer = layer, idx = idx, hw = hw, hh = hh, id = id, edge = edge}
  end
  --- The pointer position: x, y, or nil when it is not available.
  function P.position()
    local x, y = M(POS)
    if type(x) == "number" and type(y) == "number" then return x, y end
    return nil
  end
  --- The topmost zone under (x, y), or under the last pointer position; nil when there is none.
  function P.at(x, y)
    if x == nil then x, y = P.x, P.y end
    if x == nil then return nil end
    for i = #P.zones, 1, -1 do
      local z = P.zones[i]
      if z.layer ~= nil then
        local gx, gy = M(GPOS, z.layer, z.idx)
        if type(gx) == "number" and type(gy) == "number" and math.abs(x - gx) <= z.hw and math.abs(-y - gy) <= z.hh then
          return z
        end
      elseif x >= z[1] and x < z[3] and y >= z[2] and y < z[4] then
        return z
      end
    end
    return nil
  end
  -- (Enter / A with the pointer resting on empty space is a key Accept on the current selection)
  --- True when this press belongs to the pointer: a left click, or a click over a zone while the pointer is on.
  function P.owns()
    return In(LEFT) or (P.on and In(CLICK) and P.at() ~= nil)
  end
  --- Clears the hovered zone.
  function P.forget()
    P.hot = nil
  end
  --- Hands the cursor to the keys for this frame: pointer off, hover cleared, position remembered.
  function P.key_step()
    P.on, P.hot = false, nil
    local x, y = P.position()
    if x ~= nil then P.x, P.y = x, y end
  end
  --- Clears the zones, the hover and the edge state, and remembers the pointer position.
  function P.reset()
    P.zones, P.on, P.hot, P.prev, P.edge_t = {}, false, nil, {}, 0
    P.x, P.y = P.position()
    for _, c in ipairs({LEFT, CLICK, W_UP, W_DOWN}) do Edge(c) end
    for _, ctrl in ipairs(CTRLS) do
      for _, c in ipairs(NAV) do Edge(c, ctrl) end
    end
  end
  --- One frame of pointer input; answers this frame's event table.
  function P.poll()
    local ev = {}
    local x, y = P.position()
    if x ~= nil then
      local moved = M(MOVED) == true
      if not moved and P.x ~= nil and (math.abs(x - P.x) > 1 or math.abs(y - P.y) > 1) then
        moved = true
      end
      P.x, P.y = x, y
      if moved then
        P.on, ev.moved = true, true
      end
    end
    for _, ctrl in ipairs(CTRLS) do
      for _, c in ipairs(NAV) do
        if Edge(c, ctrl) then
          ev.keys = true
        end
      end
    end
    if ev.keys and not ev.moved then
      P.on = false
    end
    local left, click = Edge(LEFT), Edge(CLICK)
    if left then
      P.on, ev.left = true, true
    end
    local z = P.on and P.at() or nil
    local id = z and z.id or nil
    ev.changed = id ~= P.hot
    P.hot, ev.hot = id, id
    if z ~= nil and (ev.moved or left) then
      ev.hover = id
    end
    if left then
      if z ~= nil then
        ev.click = id
      else
        ev.miss = true                 -- a mouse click on empty space: nothing
      end
    elseif click and P.on then
      if z ~= nil then
        ev.click = id
      else
        P.on, P.hot = false, nil
      end
    end
    if In(W_DOWN) then
      ev.wheel = 1
    elseif In(W_UP) then
      ev.wheel = -1
    end
    if z ~= nil and z.edge ~= nil then
      P.edge_t = P.edge_t - 1
      if P.edge_t <= 0 then
        ev.edge, P.edge_t = z.edge, P.REPEAT
      end
    else
      P.edge_t = 0
    end
    return ev
  end
  return P
end

--- Advanced: Constants: command hashes of the menu keys, plus held(cmd, ctrl) and new_press().
VRFW.keys = VRFW.keys or (function()
  local K = {
    UP = 1197218715, DOWN = 3259546669, LEFT = 2765147006, RIGHT = 2075023265,   -- CMD_UP / DOWN / LEFT / RIGHT
    ENTER = 1981080283,          -- CMD_ENTER: Enter, A
    ENTER_CLICK = 1651523701,    -- CMD_ENTER_CLICK: the mouse's left button, Enter, A
    BACK = 3011112225,           -- CMD_BACK
    CANCEL = 3602695835,         -- CMD_CANCEL: Esc, B
    FUNC3 = 3421673595, FUNC4 = 1435897304,                    -- CMD_FUNC3 / CMD_FUNC4
    L1 = 3966226594, R1 = 942075773, L2 = 1970176280, R2 = 2704260807,   -- CMD_FUNCL1 / R1 / L2 / R2
    MOUSE_LEFT = 749879980,      -- CMD_VRFW_MOUSE_LEFT: the mouse's left button alone
    MOUSE_RIGHT_CLICK = 3473063670,                            -- CMD_MOUSE_RIGHT_CLICK
    WHEEL_UP = 2649361876, WHEEL_DOWN = 1098743808,            -- CMD_VRFW_WHEEL_UP / _DOWN
    MENU_CTRL = 1332654303,      -- the menu control
    MENU_CTRL_ANALOG = 2748927068,   -- MENU_CTRL_WITH_ANALOG_MOVE_FOCUS: the stick's menu moves
    CHECK_INPUT = 4265778440,    -- CMND_CHECK_INPUT_CMD (control, command) -> true while held
  }
  K.CONTROLS = {K.MENU_CTRL, K.MENU_CTRL_ANALOG}
  --- True when input cmd is held; with ctrl, on that controller only.
  function K.held(cmd, ctrl)
    if ctrl ~= nil then
      local ok, r = pcall(funcLuaCommand, K.CHECK_INPUT, ctrl, cmd)
      return ok and r == true
    end
    for _, c in ipairs(K.CONTROLS) do
      local ok, r = pcall(funcLuaCommand, K.CHECK_INPUT, c, cmd)
      if ok and r == true then
        return true
      end
    end
    return false
  end
  --- A press tracker; answers a table with pressed(cmd, ctrl) and reset().
  function K.new_press()
    local held = {}
    local T = {}
    --- True on the frame cmd goes down, once per press.
    function T.pressed(cmd, ctrl)
      local key = tostring(ctrl or "any") .. ":" .. tostring(cmd)
      local now = K.held(cmd, ctrl)
      local was = held[key]
      held[key] = now
      return now and not was
    end
    --- Treats every key as already held, so a key still down after a reset is no press.
    function T.reset()
      held = setmetatable({}, {__index = function() return true end})
    end
    return T
  end
  return K
end)()
local Kit, Ptr                  -- set in OnInit

--- Advanced: Namespace: 3D character model preview helper for menus; holds new().
VRFW.chara_model = VRFW.chara_model or {}
--- Advanced: Creates a character model preview (layer, opts); answers a table with show(pid), show_chara(chara, motion), hide, release, ok and step.
VRFW.chara_model.new = VRFW.chara_model.new or function(layer, opts)
  opts = opts or {}
  local M = {pid = nil, chara = nil, pend = nil, build = nil, hide_build = false, logs = 0, failed = false,
    SHADOW = opts.shadow or 858725131 --[[mainmenu01_08_chara_3d_shadow]], POSE = opts.pose or 2328706751,
    SETTLE = opts.settle or 2, MIN = opts.min or 6, MAX = opts.max or 120, SLOT = opts.slot or 0}
  M.KEY = opts.key or M.SLOT
  local FREE_FRAMES = opts.free_frames or 2
  local function MC(cmd, ...)
    local ok, a, b = pcall(funcLuaMenuCommand, cmd, ...)
    if ok then return a, b end
    return nil
  end
  local function Log(...)
    if opts.log ~= nil and M.logs < 12 then
      M.logs = M.logs + 1
      pcall(opts.log, "model", ...)
    end
  end
  local function Visible(on)
    local h = MC(3895705890, layer, 0, M.SLOT)
    if type(h) == "number" and h ~= 0 then
      pcall(funcLuaCommand, 1890282463, h, on)
    end
  end
  local function Ready()
    return MC(1583438030, layer, 0, M.SLOT) == true
  end
  local function Loading(chara)
    local ok, l = pcall(funcLuaCommand, 2475005551, chara)
    return ok and l == true
  end
  local function BuildDone()
    return M.build == nil or M.build.done
  end
  -- Returns the character's body type, as retail shop_menu_buy passes it to SetupCharaModel.
  local function BodyType(chara)
    local ok, has, v = pcall(funcLuaCommand, 4060384944 --[[CMND_GET_CHARA_INFO]], chara, 3, 0)
    if ok and has == true and type(v) == "number" then
      return v
    end
    return 0
  end
  local function Setup(chara, pid, motion, n, uniform, flags)
    MC(59611540, layer, 0, chara, M.SLOT)
    MC(186863317 --[[CMND_SET_SCN_CHARA_REGIST_TYPE]], layer, 0, 4, M.SLOT)
    MC(3290636356, layer, 0, uniform, motion, flags, M.SLOT)
    MC(4219344099 --[[CMND_SET_CHARA_MODEL_SHADOW?]], layer, 0, M.SHADOW, M.SLOT, M.SLOT)
    MC(2232914067 --[[CMND_CHARA_MODEL_CHANGE]], layer, 0, 0, 9, M.SLOT, M.KEY)
    if opts.bodies ~= nil and opts.bodies[n] then   -- only a body type the pose lists (see CRASH GUARD above)
      MC(2450020144, layer, 0, M.POSE, n, M.SLOT)
    end
  end
  local function BuildStep()
    local B = M.build
    if B == nil or B.done then
      return
    end
    B.n = B.n + 1
    if not Ready() then
      B.seen, B.ok = true, 0
    elseif B.seen or B.n >= M.MIN then
      B.ok = B.ok + 1
    end
    if B.ok >= M.SETTLE or B.n >= M.MAX then
      B.done = true
      if not B.seen and B.ok < M.SETTLE then
        M.failed = true
      end
      Log("ready", B.n, tostring(B.seen), tostring(B.ok >= M.SETTLE))
    end
  end
  local function PendStep()
    local P = M.pend
    if P == nil then
      if M.hide_build then
        Visible(false)
        M.hide_build = not BuildDone()
      end
      return
    end
    M.hide_build = false
    P.n = P.n + 1
    if not P.built then
      if P.n < M.MAX and (not BuildDone() or Loading(P.chara)) then
        Visible(false)
        return
      end
      local ok, err = pcall(Setup, P.chara, P.pid, P.motion, P.body, P.uniform, P.flags)
      Visible(false)
      P.built, P.n = true, 0
      M.build = {n = 0, seen = false, ok = 0, done = false}
      M.pid, M.chara, M.clip = P.pid, P.chara, P.clip
      Log("build", P.pid, P.chara, P.motion, string.format("uniform 0x%08X flags %d", P.uniform, P.flags), tostring(ok),
        tostring(err))
      return
    end
    if not BuildDone() then
      Visible(false)
      return
    end
    Visible(true)
    if M.clip ~= nil then
      MC(180466856, layer, 0, M.clip, 0, 0, 0, 0, M.SLOT)   -- Plays the model's stand clip, as retail shop_menu_buy does.
    end
    M.pend = nil
    Log("shown", P.pid, P.n)
  end
  --- True while the model view has not failed.
  function M.ok()
    return not M.failed
  end
  --- Hides the model and cancels a pending show.
  function M.hide()
    M.pend = nil
    M.hide_build = not BuildDone()
    if M.pid ~= nil then
      Visible(false)
    end
  end
  -- a build or a model load of this slot still under way (retail SetupCharaModel never changes a model mid-load)
  local function Busy()
    return not BuildDone() or (M.chara ~= nil and Loading(M.chara))
  end
  -- Hides the model and frees the slot.
  local function Free()
    Visible(false)
    MC(59611540, layer, 0, 0, M.SLOT)
    -- Clears the slot's own model key.
    MC(2232914067 --[[CMND_CHARA_MODEL_CHANGE]], layer, 0, 0, 9, M.SLOT, M.KEY)
    Log("released", M.pid)
    M.pid, M.chara, M.build, M.release_wanted = nil, nil, nil, false
    M.free_frames = FREE_FRAMES
  end
  --- Releases the slot's model, like retail shop ResetCharaModel.
  function M.release()
    M.pend, M.hide_build = nil, false
    if M.pid == nil then
      M.release_wanted = false
      return
    end
    if Busy() then
      Visible(false)
      if not M.release_wanted then
        M.release_wanted = true
        Log("release waits for the load", M.pid)
      end
      return
    end
    Free()
  end
  --- Returns true once nothing is held.
  function M.released()
    return M.pid == nil and not M.release_wanted and (M.free_frames or 0) <= 0
  end
  --- Shows player param pid in the model view, building it when needed.
  function M.show(pid)
    M.release_wanted = false
    local P = M.pend
    if P ~= nil and P.pid == pid then
      return
    end
    if P == nil and M.pid == pid then
      if BuildDone() then
        Visible(true)
      else
        M.pend = {pid = pid, chara = M.chara, n = 0, built = true}
      end
      return
    end
    local ok, chara = pcall(funcLuaCommand, 347353059 --[[chara of chara_param]], pid)
    if not ok or type(chara) ~= "number" or chara == 0 then
      Log("none", pid)
      M.hide()
      return
    end
    local motion = 1
    local ok2, has, v = pcall(funcLuaCommand, 4060384944 --[[CMND_GET_CHARA_INFO]], pid, 21)
    if ok2 and has == true and type(v) == "number" and v ~= 0 then
      motion = v
    end
    local body = BodyType(chara)
    if opts.bodies == nil or not opts.bodies[body] then
      Log("skip body", pid, chara, body, tostring(opts.bodies ~= nil))
      M.hide()
      return
    end
    -- Reads the uniform and look options of the kit.
    local uniform, flags = opts.uniform or 0, opts.look or 0
    if opts.kit ~= nil then
      local okk, u, f = pcall(opts.kit, pid)
      if okk and type(u) == "number" and u ~= 0 then
        uniform = u
      end
      if okk and type(f) == "number" then
        for _, bit in ipairs({2, 16, 32}) do
          if math.floor(f / bit) % 2 == 1 and math.floor(flags / bit) % 2 == 0 then
            flags = flags + bit
          end
        end
      end
    end
    Visible(false)
    M.pend = {pid = pid, chara = chara, motion = motion, body = body, uniform = uniform, flags = flags, n = 0,
      built = false}
    PendStep()
  end
  --- Shows character id chara itself, for a model of its own (a spirit, a prop): no kit, no pose; motion = its stand clip or nil.
  function M.show_chara(chara, motion)
    M.release_wanted = false
    if type(chara) ~= "number" or chara == 0 then
      M.hide()
      return
    end
    local P = M.pend
    if P ~= nil and P.pid == chara then
      return
    end
    if P == nil and M.pid == chara then
      if BuildDone() then
        Visible(true)
      else
        M.pend = {pid = chara, chara = M.chara, n = 0, built = true}
      end
      return
    end
    Visible(false)
    M.pend = {pid = chara, chara = chara, motion = 1, body = -1, uniform = 0, flags = 0, clip = motion, n = 0,
      built = false}
    PendStep()
  end
  --- One frame of the model view: advances the build and a pending release.
  function M.step()
    BuildStep()
    if M.release_wanted then
      Visible(false)
      if not Busy() then
        Free()
      end
      return
    end
    if (M.free_frames or 0) > 0 then
      M.free_frames = M.free_frames - 1
    end
    PendStep()
  end
  return M
end

local function Str(v)
  if type(v) == "string" then
    return v
  elseif type(v) == "number" then
    return v ~= 0 and Kit.text(v) or ""
  elseif type(v) == "table" then
    local s = type(v.id) == "number" and Kit.text(v.id) or tostring(v.text or "")
    if type(v.args) == "table" and #v.args > 0 then
      local ok, f = pcall(string.format, s, table.unpack(v.args))
      if ok then s = f end
    end
    if type(v.vars) == "table" then
      for k, x in pairs(v.vars) do
        s = s:gsub("{" .. tostring(k) .. "}", (tostring(x):gsub("%%", "%%%%")))
      end
    end
    return s
  end
  return ""
end

-- Draws the next plate of the pool.
local function Plate(role, x, y, w, h, priority)
  if used.plate >= N.PLATE then
    return
  end
  Kit.art_quad(L_PLATE, used.plate, role, x + w / 2, y + h / 2, w, h)
  pcall(funcLuaMenuCommand, C.DRAW_PRIORITY, L_PLATE, used.plate, priority or C.PLATE_PRIORITY, true)
  used.plate = used.plate + 1
end

-- Draws the next text line of the pool.
local function Line(s, x, y, scale, dark)
  if s == nil or s == "" or used.text >= N.TEXT then
    return
  end
  local idx = used.text
  used.text = used.text + 1
  local node, other = dark and TEXT_OFF or TEXT_ON, dark and TEXT_ON or TEXT_OFF
  Kit.show(L_TEXT, idx)
  Kit.scale(L_TEXT, idx, scale, scale)
  funcLuaMenuCommand(C.TEXT, L_TEXT, node, s, idx)
  funcLuaMenuCommand(C.TEXT_VISIBLE, L_TEXT, node, true, idx)
  funcLuaMenuCommand(C.TEXT_VISIBLE, L_TEXT, other, false, idx)
  Kit.place(L_TEXT, idx, x - TEXT_DX * scale, y)
end

-- `s` cut into lines of at most `w` px at `scale` (by words)
local function Wrap(s, w, scale)
  local max = math.max(4, math.floor(w / (WRAP_W * scale)))
  local out, cur = {}, ""
  for word in string.gmatch(s, "%S+") do
    local next = cur == "" and word or (cur .. " " .. word)
    if #next > max and cur ~= "" then
      out[#out + 1] = cur
      cur = word
    else
      cur = next
    end
  end
  if cur ~= "" then
    out[#out + 1] = cur
  end
  return out
end

local function Row(i)
  if rows[i] == nil then
    local r = Call(DECL.source, CTX, i)
    rows[i] = type(r) == "table" and r or false
  end
  return rows[i] or nil
end

local function ModelsOf(r)
  local out = {}
  for _, m in ipairs(type(r) == "table" and type(r.models) == "table" and r.models or {}) do
    if type(m) == "table" and type(m.card) == "number" and m.card ~= 0 then
      out[#out + 1] = m
    end
  end
  return out
end

-- the models of the page shown (DECL.models a page) and the page count
function NP.page_rows(r)
  local all = ModelsOf(r)
  local per = DECL.models
  local pages = math.max(1, math.ceil(#all / per))
  NP.page = math.max(1, math.min(NP.page, pages))
  local out = {}
  for k = (NP.page - 1) * per + 1, math.min(#all, NP.page * per) do
    out[#out + 1] = all[k]
  end
  return out, pages
end

-- the layout of the declaration's style (content\defaults\pose_row.toml [layout] / [layout.<style>])
function NP.layout()
  local L = DECL and DECL.layout or {}
  if DECL and DECL.style == "node_panel" and type(L.node_panel) == "table" then
    return L.node_panel
  end
  return L
end

-- name and position of the entry's cards (asked once per card)
local function CardsOf(list)
  local need = {}
  for _, m in ipairs(list) do
    if cards[m.card] == nil then
      need[#need + 1] = m.card
    end
  end
  if #need > 0 then
    local r = Call(C.ROW_CARDS, lang, table.unpack(need))
    for k, c in ipairs(need) do
      local v = type(r) == "table" and r[k] or nil
      cards[c] = type(v) == "table" and v or {name = "", position = 0}
    end
  end
end

local function Owned(card)
  return VRFW.recruit ~= nil and VRFW.recruit.owned(card) > 0
end

local function SlotX(Lo, k)
  return (Lo.slot_x or {})[k] or 960
end

-- Returns a slot's world place from the layout.
local function SlotWorld(k)
  local Lo, Ca = NP.layout(), DECL.camera or {}
  local mz = Lo.model_z or Ca.model_z or -2.35
  local d = (Ca.eye_z or 12.5) - mz
  local ppm = (Ca.px_per_m_at_1m or 3060) / d
  local sx = SlotX(Lo, k)
  local look = (Ca.look_y or 1.6) + ((Ca.eye_y or 2.25) - (Ca.look_y or 1.6)) * mz / (Ca.eye_z or 12.5)
  return (sx - 960) / ppm, look - ((Lo.feet_y or 668) - 540) / ppm, mz
end

local function ApplyModels()
  local list = NP.page_rows(Row(focus))
  for k = 1, DECL.models do
    local M = models[k]
    local m = list[k]
    local card = m and m.card or nil
    if M ~= nil and shown[k] ~= card then
      if shown[k] ~= nil then
        M.release()
      end
      placed[k] = nil
      shown[k] = card
      if card ~= nil then
        M.show(card)
      end
    end
  end
end

-- Steps every slot shown.
local function ModelStep()
  for k, M in pairs(models) do
    M.step()
    local B = M.build
    if B ~= nil and B.done and M.pend == nil and M.pid ~= nil and placed[k] ~= B then
      placed[k] = B
      local x, y, z = SlotWorld(k)
      pcall(funcLuaMenuCommand, C.MODEL_POS, L_MODEL, 0, x, y, z, k - 1)
      pcall(funcLuaMenuCommand, C.MODEL_TURN, L_MODEL, 0, false)
      Log("slot", k, "card", M.pid, "at", string.format("%.2f %.2f %.2f", x, y, z))
    end
  end
end

local function ReleaseModels()
  for k, M in pairs(models) do
    M.release()
    shown[k], placed[k] = nil, nil
  end
end

local function UpdateTitle()
  if DECL ~= nil and DECL.style == "node_panel" then
    -- Over the board the header is off and the title is the title band's (NP.draw).
    funcLuaMenuCommand(C.TEXT, L_HEADER, 1220590795 --[[_text_sub_title02]], "", 0)
    funcLuaMenuCommand(C.LAYER_VISIBLE, L_HEADER, 0, false)
    return
  end
  local title = Kit.text(DECL and DECL.title or 0)
  local sub = HEAD and Str(HEAD.title) or ""
  if sub ~= "" then
    title = title ~= "" and (title .. " · " .. sub) or sub
  end
  funcLuaMenuCommand(C.TEXT, L_HEADER, 1220590795 --[[_text_sub_title02]], title, 0)
end

local function UpdateButtonGuide()
  local accept = (DECL ~= nil and DECL.decide ~= 0) and DECL.decide or G_ACCEPT
  local texts, icons, offs, keys = {accept}, {I_ENTER}, {18}, {K_ENTER}
  if DECL ~= nil and DECL.team ~= 0 then
    texts[2], icons[2], offs[2], keys[2] = DECL.team, I_FUNC3, 36, K_FUNC3
  end
  funcLuaMenuCommand(C.GUIDE_SET, MENU, L_BTN_GUIDE, texts, icons, offs, {}, {})
  funcLuaMenuCommand(C.GUIDE_CMD, MENU, L_BTN_GUIDE, keys)
  funcLuaMenuCommand(C.GUIDE_OPT, MENU, L_BTN_GUIDE, false)
end

local function DrawList(Lo)
  local L = Lo.list or {}
  local per = Lo.rows or 10
  local first = math.max(1, math.min(focus - math.floor(per / 2), count - per + 1))
  for k = 0, per - 1 do
    local i = first + k
    local r = i <= count and Row(i) or nil
    if r ~= nil then
      local x, y, w, h = L.x or 60, (L.y or 160) + k * ((L.h or 74) + (L.gap or 8)), L.w or 560, L.h or 74
      local on = i == focus
      Plate(on and "list_row_focus" or "list_row", x, y, w, h)
      local badge = Str(r.tag)
      if badge ~= "" then
        Plate("list_badge", x + 10, y + 12, 50, h - 24)
        Line(badge, x + 16, y + h / 2, 0.55, false)
      end
      Line(Str(r.label), x + 78, y + h * 0.36, 0.95, true)
      Line(Str(r.sub), x + 78, y + h * 0.72, 0.62, true)
      pos[i] = {x = x + w / 2, y = y + h / 2, hw = w / 2, hh = h / 2}
    end
  end
end

-- Draws the entry's panel.
local function DrawPanel(Lo)
  local P = Lo.panel or {}
  Kit.art_quad(L_GROUND, 0, "panel_ground", (P.x or 650) + (P.w or 1220) / 2, (P.y or 160) + (P.h or 800) / 2, P.w or 1220,
    P.h or 800)
  local r = Row(focus)
  if r == nil then
    return
  end
  local ti, inf, hi = Lo.title or {}, Lo.info or {}, Lo.hint or {}
  Line(Str(r.title or r.label), ti.x or 686, ti.y or 196, ti.scale or 1.25, false)
  Line(Str(r.info), inf.x or 686, inf.y or 246, inf.scale or 0.8, false)
  Line(Kit.text(DECL.hint), hi.x or 686, hi.y or 928, hi.scale or 0.75, false)
  NP.cards(Lo, (NP.page_rows(r)))
end

-- a card under each model of the page shown
function NP.cards(Lo, list)
  CardsOf(list)
  local K = Lo.card or {}
  local cw, ch, cy, bar = K.w or 230, K.h or 196, K.y or 700, K.bar or 6
  for k, m in ipairs(list) do
    local cx = SlotX(Lo, k)
    local x = cx - cw / 2
    local c = cards[m.card] or {}
    local p = Int(c.position)
    Plate("card", x, cy, cw, ch)
    Plate("position_" .. (p >= 1 and p <= 4 and p or 1), x, cy, cw, bar)
    Line(c.name or "", x + 12, cy + 26, 0.68, true)
    Plate("position_" .. (p >= 1 and p <= 4 and p or 1), x + 10, cy + 46, 46, 26)
    Line(Kit.text(T.POS[p] or 0), x + 16, cy + 59, 0.5, false)
    local owned = Owned(m.card)
    Plate(owned and "tag_owned" or "tag_new", x + 62, cy + 46, cw - 72, 26)
    Line(owned and (MARK_ON .. Kit.text(DECL.owned)) or Kit.text(DECL.new), x + 72, cy + 59, 0.5, not owned)
    local text = Str(m.text)
    if m.done == true and text ~= "" then
      text = MARK_ON .. text
    end
    local label = text ~= "" and Kit.text(DECL.label or 0) or ""
    local top = cy + 96
    if label ~= "" then
      Line(label, x + 12, top, 0.55, true)
      top = top + 26
    end
    local lines = Wrap(text, cw - 24, 0.55)
    for n = 1, math.min(label ~= "" and 3 or 4, #lines) do
      Line(lines[n], x + 12, top + (n - 1) * 26, 0.55, true)
    end
  end
end

function NP.draw(Lo)
  local function box(t, d) return t or d end
  local r = Row(focus)
  local Ti = box(Lo.title, {})
  Plate("title_band", Ti.x or 40, Ti.y or 42, Ti.w or 890, Ti.h or 70)
  local title = Kit.text(DECL.title)
  local sub = HEAD and Str(HEAD.title) or ""
  if sub ~= "" then title = title ~= "" and (title .. " · " .. sub) or sub end
  Line(title, (Ti.x or 40) + 50, (Ti.y or 42) + (Ti.h or 70) / 2, Ti.scale or 1.15, false)
  local Bn = box(Lo.banner, {})
  Plate("banner", Bn.x or 90, Bn.y or 190, Bn.w or 530, Bn.h or 160)
  Line(Kit.text(DECL.banner), (Bn.x or 90) + 30, (Bn.y or 190) + (Bn.h or 160) - 40, Bn.scale or 1, false)
  if DECL.icon_atlas ~= "" and used.plate < N.PLATE then
    local Ic = box(Bn.icon, {})
    Kit.textured_quad(L_PLATE, used.plate, CRC32(DECL.icon_atlas), CRC32(DECL.icon_sprite), Ic.x or 515, Ic.y or 265, Ic.size or 150,
      Ic.size or 150)
    used.plate = used.plate + 1
  end
  -- Draws the rows.
  local Rw = box(Lo.rows, {})
  local shown, step = Rw.shown or 5, Rw.step or 70
  local first = NP.first or 1
  if focus < first then first = focus end
  if focus > first + shown - 1 then first = focus - shown + 1 end
  first = math.max(1, math.min(first, math.max(1, count - shown + 1)))
  NP.first = first
  for k = 0, shown - 1 do
    local i = first + k
    local e = i <= count and Row(i) or nil
    if e ~= nil then
      local x, y, w, h = Rw.x or 90, (Rw.y or 380) + k * step, Rw.w or 540, Rw.h or 52
      Plate(i == focus and "row_focus" or "row", x, y, w, h)
      Plate("level_circle", x + 12, y + 4, h - 8, h - 8)
      local lv = tostring(Int(e.level))
      Line(lv, x + 12 + (h - 8) / 2 - #lv * CHAR_W * 0.55 / 2, y + h / 2, 0.55, true)
      Line(Str(e.label), x + h + 24, y + h / 2, Rw.scale or 0.85, i ~= focus)
      if e.done == true then
        if art.check ~= nil then
          Plate("check", x + w - 64, y + (h - 44) / 2, 44, 44)
        else
          Line(MARK_ON, x + w - 60, y + h / 2, 0.8, i ~= focus)
        end
      end
      pos[i] = {x = x + w / 2, y = y + h / 2, hw = w / 2, hh = h / 2}
    end
  end
  -- Draws the list's scroll arrows (art roles arrow_up and arrow_down).
  local Ar = box(Lo.arrows, {})
  local aw, ah = Ar.w or 44, Ar.h or 32
  local ax = Ar.x or ((Rw.x or 90) + (Rw.w or 540) - aw - 18)
  if first > 1 then
    Plate("arrow_up", ax, Ar.up_y or ((Rw.y or 380) - ah - 2), aw, ah, C.PLATE_PRIORITY + 1)
  end
  if first + shown - 1 < count then
    Plate("arrow_down", ax, Ar.down_y or ((Rw.y or 380) + (shown - 1) * step + (Rw.h or 52) + 4), aw, ah,
      C.PLATE_PRIORITY + 1)
  end
  local Mo = box(Lo.more, {})
  local more_text = HEAD and Str(HEAD.info) or ""
  if more_text ~= "" then
    Plate("label_plate", (Mo.x or 300) - 20, (Mo.y or 745) - 20, #more_text * CHAR_W * (Mo.scale or 0.6) + 40, 40)
    Line(more_text, Mo.x or 300, Mo.y or 745, Mo.scale or 0.6, false)
  end
  if r == nil then
    return
  end
  -- Draws the lineup of the selected entry.
  NP.lineup(Lo, r)
  if DECL.team ~= 0 then
    local Tm = box(Lo.team, {})
    local tt = Kit.text(DECL.team)
    local tw = #tt * CHAR_W * (Tm.scale or 0.7)
    Plate("button_plate", (Tm.x or 360) - tw / 2 - 30, (Tm.y or 976) - 22, tw + 60, 44)
    Line(tt, (Tm.x or 360) - tw / 2, Tm.y or 976, Tm.scale or 0.7, false)
  end
  -- Draws the side panel.
  local P = box(Lo.panel, {})
  Kit.art_quad(L_GROUND, 0, "side_panel", (P.x or 700) + (P.w or 1130) / 2, (P.y or 165) + (P.h or 770) / 2, P.w or 1130, P.h or 770)
  local Pt, Pi, Pg = box(Lo.panel_title, {}), box(Lo.panel_info, {}), box(Lo.page, {})
  Line(Kit.text(DECL.panel_title), Pt.x or 710, Pt.y or 130, Pt.scale or 1.1, false)
  local info = Str(r.title or r.label)
  local more = Str(r.info)
  Line(more ~= "" and (info .. "   ·   " .. more) or info, Pi.x or 730, Pi.y or 205, Pi.scale or 0.8, false)
  local list, pages = NP.page_rows(r)
  if pages > 1 then
    local ok, ptxt = pcall(string.format, Kit.text(DECL.page), NP.page, pages)
    Line(ok and ptxt or (NP.page .. " / " .. pages), Pg.x or 1650, Pg.y or 205, Pg.scale or 0.7, false)
  end
  NP.player_rows(Lo, list)
end

-- Draws one row per player of the page under the models.
function NP.player_rows(Lo, list)
  CardsOf(list)
  local R = Lo.player_rows or {}
  local x, y0, w, h, step = R.x or 740, R.y or 648, R.w or 1050, R.h or 46, R.step or 54
  local ns, ts, tx = R.name_scale or 0.62, R.text_scale or 0.55, R.text_x or 340
  for k, m in ipairs(list) do
    local y = y0 + (k - 1) * step
    -- A model with no_check = true is only shown.
    local owned = m.no_check ~= true and Owned(m.card)
    Plate(owned and "player_row_off" or "player_row", x, y, w, h)
    if m.no_check ~= true then
      Plate("check_box", x + 14, y + (h - 32) / 2, 32, 32, C.PLATE_PRIORITY + 1)
      if owned or m.done == true then
        Plate("check_mark", x + 10, y + (h - 40) / 2 - 4, 40, 40, C.PLATE_PRIORITY + 2)
      end
    end
    local c = cards[m.card] or {}
    Line(c.name or "", x + 64, y + h / 2, ns, not owned)
    local text = Str(m.text)
    local max = math.max(4, math.floor((w - tx - 20) / (WRAP_W * ts)))
    if #text > max then
      text = string.sub(text, 1, max - 3) .. "..."
    end
    Line(text, x + tx, y + h / 2, ts, not owned)
  end
end

